import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> [side, price, qty_remaining, seq]

    def clean_buy():
        while buy_heap and buy_heap[0][2] not in book:
            heapq.heappop(buy_heap)

    def clean_sell():
        while sell_heap and sell_heap[0][2] not in book:
            heapq.heappop(sell_heap)

    def add_resting(id_, side, price, qty, seq):
        book[id_] = [side, price, qty, seq]
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id_))
        else:
            heapq.heappush(sell_heap, (price, seq, id_))

    for idx, o in enumerate(orders):
        seq = idx
        typ = o[0]

        if typ == 'cancel':
            id_ = o[1]
            if id_ in book:
                del book[id_]
            continue

        if typ == 'limit':
            _, id_, side, price, qty = o
        elif typ == 'ioc':
            _, id_, side, price, qty = o
        else:  # market
            _, id_, side, qty = o
            price = None

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                p, s, sid = sell_heap[0]
                if typ != 'market' and p > price:
                    break
                sqty = book[sid][2]
                traded = min(remaining, sqty)
                trades.append([id_, sid, p, traded])
                remaining -= traded
                book[sid][2] -= traded
                if book[sid][2] == 0:
                    del book[sid]
                    heapq.heappop(sell_heap)
            if typ == 'limit' and remaining > 0:
                add_resting(id_, 'buy', price, remaining, seq)

        else:  # side == 'sell'
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, s, bid = buy_heap[0]
                p = -negp
                if typ != 'market' and p < price:
                    break
                bqty = book[bid][2]
                traded = min(remaining, bqty)
                trades.append([bid, id_, p, traded])
                remaining -= traded
                book[bid][2] -= traded
                if book[bid][2] == 0:
                    del book[bid]
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                add_resting(id_, 'sell', price, remaining, seq)

    return trades

